package pe.com.dentalamericana.finance;import jakarta.persistence.*;@Entity@Table(name="metodos_pago")public class PaymentMethod{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,unique=true)private String codigo;@Column(nullable=false)private String nombre;@Column(name="requiere_referencia",nullable=false)private boolean referenceRequired;@Column(nullable=false)private boolean activo=true;protected PaymentMethod(){}public Long getId(){return id;}public String getCode(){return codigo;}public String getName(){return nombre;}public boolean isReferenceRequired(){return referenceRequired;}public boolean isActive(){return activo;}}
